export const isRecentSettled = (c: Claim, today: string | undefined) =>
  today !== undefined && c.status === 'SETTLED' && c.date > daysBefore(today, 90) && c.date <= today;

/** Under the sheet's key, so loading the sheet again re-reads its claims. */
export const claimsKey = (sheet: string) => [...sheetKey(sheet), 'claims'] as const;

/** Under the claims' key, so whatever re-reads the claims re-reads the tags too. */
export const tagsKey = (sheet: string) => [...claimsKey(sheet), 'tags'] as const;

/** Every tag ever carried by a claim on the sheet, sorted. */
export function useTags(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(tagsKey(sheet), asOf),
    queryFn: () => getJson<string[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/tags`, asOf)),
    enabled: sheet !== '',
  });
}

/** Every claim on the sheet, newest first. */
export function useClaims(sheet: string) {
  const [asOf] = useAsOf();
  return useQuery({
    queryKey: asOfKey(claimsKey(sheet), asOf),
    queryFn: () => getJson<Claim[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/claims`, asOf)),
    enabled: sheet !== '',
  });
}

/** Amounts are added in whole cents, so the sum is exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether the claim corrects another: it names the number of the claim it corrects. */
export const correctsAnother = (c: Claim) => c.corrects !== null && c.corrects.trim() !== '';

/** The sum of the amounts of those of these claims that count, leaving out claims that correct another,
 *  with two decimals. */
export function claimed(claims: Claim[]): string {
  return (claims.filter((c) => counts(c) && !correctsAnother(c)).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}

/** The ids of the claims selected for a bulk action, kept in the URL (`selectedClaims`, comma separated). */
export function useSelectedClaims(): [number[], (ids: number[]) => void] {
  const [raw, setRaw] = useSearchParam('selectedClaims', asString);
  const ids = raw.split(',').filter((s) => s !== '').map(Number).filter((n) => !Number.isNaN(n));
  return [ids, (next) => setRaw(next.join(','))];
 *  {@code graceDays} is the whole days after its to-date an open period is closed by a new today, null when blank (off).
 *  {@code entryDate} is the default date of a new claim in place of the sheet's today, null when blank (off).
 *  {@code gradeGrace} is each grade's grace days in force on the sheet's today, by grade, null when it has none;
 *  {@code gradeGraceFrom} is each grade's grace days recorded, by grade, oldest from-date first (a claim's grace is the
 *  one in force on its date for its person's grade then).
 *  {@code gradeProofThreshold} is each grade's proof threshold in force on the sheet's today, by grade, null when it has
 *  none (a claim's proof threshold is its person's grade's in force on its date when one is set, else the sheet's).
 *  {@code pot} has two decimals, the sum shared out among a balanced pool's members, null for none (not dated).
 *  {@code parent} is the id of the sheet whose rates a grade with no rate in force on a date takes, null for none (not dated;
 *  the one named now, also as of a date).
 *  {@code fiscalStartMonth} is the month (1 to 12) a fiscal year starts in, 1 unless set (not dated).
 *  {@code alertThreshold} has two decimals, the due-total above which a person crossing it raises an ALERT, null for
 *  off (not dated).
 *  {@code rounding} is the rounding mode in force on the sheet's today (half-up or half-even), null when none;
 *  {@code roundingFrom} is the rounding modes recorded, oldest from-date first (a claim rounds by the one in force on
 *  its date, else by the policy date).
 *  {@code reviewThreshold} has two decimals, the due above which a claim goes to REVIEW when opened, in force on the
 *  sheet's today, null for none.
 *  {@code escalateAfter} is the whole days at least between a claim's previous reminder and the sheet's today for a
 *  reminder to escalate it (once per claim), null for off (not dated).
 *  {@code reviewSla} is the whole days after its review day a claim in REVIEW may stay there before it is late, null
 *  for none (not dated).
 *  {@code proofKinds} is the kinds of proof a claim above its proof threshold needs one of each of before it is settled
 *  or approved, comma separated, null for none (not dated).
 *  {@code defaultGrade} is the grade the quick-add bar and an import line with a blank grade give a new person, null
 *  when blank (then A; not dated).
 *  {@code gradeClerkLimit} is each grade's clerk limit in force on the sheet's today, by grade, null when it has none
 *  (a claim's clerk limit is its person's grade's in force on its date when one is set, else the sheet's then).
 *  {@code scoreMid} and {@code scoreHigh} are the whole-number scores at or above which a person's band is MID and
 *  HIGH, null when blank (no band while either is; not dated).
 *  {@code scoreLog} is on while moving the sheet's today records each person's score, null when blank (not dated).
 *  {@code maxOpen} is the most OPEN or PENDING claims a person may have for another to be opened, null for none
 *  (not dated).
 *  {@code pendingSla} is the whole days after its pending day a claim in PENDING may stay there before it is late,
 *  null for none (not dated).
 *  {@code policyVersion} is the sheet's current policy version: the number of changes made to its policy settings
